import {
  forwardRef,
  useImperativeHandle,
  useRef,
  type CSSProperties
} from "react";
import { Canvas } from "@react-three/fiber";
import type { RuntimeStatus, StarFieldConfig } from "@/components/formfield/domain";
import { getGeometryDefinition } from "@/components/formfield/geometries/registry";
import { StarScene, type StarFieldController } from "@/components/formfield/StarScene";
import "@/components/formfield/star-field.css";

export interface StarFieldHandle {
  resetView(): void;
}

export interface StarFieldProps {
  config: StarFieldConfig;
  className?: string;
  style?: CSSProperties;
  onRuntimeStatusChange?: (status: RuntimeStatus) => void;
}

export const StarField = forwardRef<StarFieldHandle, StarFieldProps>(function StarField(
  { config, className = "", style, onRuntimeStatusChange },
  forwardedRef
) {
  const controllerRef = useRef<StarFieldController | null>(null);
  const definition = getGeometryDefinition(config.shape);

  useImperativeHandle(forwardedRef, () => ({
    resetView: () => controllerRef.current?.resetView()
  }), []);

  return (
    <div
      className={`star-field ${className}`.trim()}
      style={{ background: config.theme.background, ...style }}
      role="img"
      aria-label={definition.ariaLabel}
    >
      <Canvas
        camera={{ fov: 60, near: 1, far: 1600, position: [0, 0, 519.615] }}
        dpr={[1, 1.75]}
        gl={{ antialias: false, alpha: false, powerPreference: "high-performance" }}
        performance={{ min: 0.65 }}
      >
        <StarScene
          config={config}
          controllerRef={controllerRef}
          onRuntimeStatusChange={onRuntimeStatusChange}
        />
      </Canvas>
    </div>
  );
});

import { useEffect, useMemo, useRef } from "react";
import { useFrame, useThree } from "@react-three/fiber";
import * as THREE from "three";
import { LineMaterial } from "three/examples/jsm/lines/LineMaterial.js";
import { LineSegments2 } from "three/examples/jsm/lines/LineSegments2.js";
import { LineSegmentsGeometry } from "three/examples/jsm/lines/LineSegmentsGeometry.js";
import type { StarFieldConfig } from "@/components/formfield/domain";
import { DustTrailLayer, StarPointLayer } from "@/components/formfield/effects/RenderLayers";
import { getGeometryDefinition } from "@/components/formfield/geometries/registry";
import { GRID_COLUMNS, GRID_ROWS, POINT_COUNT } from "@/components/formfield/geometries/types";
import {
  ENERGY_WAVE_BAND_WIDTH,
  ENERGY_WAVE_COUNT,
  type StarRuntime
} from "@/components/formfield/StarRuntime";
import { starFragmentShader, starVertexShader } from "@/components/formfield/starShaders";

const FLOW_PHASE_PER_SECOND = Math.PI / 40 * 1.2;
const BASE_SCENE_SCALE = 0.66;
const TRAIL_POINT_STEP = 2;
const TRAIL_SEGMENT_COUNT = Math.ceil(POINT_COUNT / TRAIL_POINT_STEP);
const TRAIL_VISIBILITY_THRESHOLD = 0.04;

interface StarParticlesProps {
  config: StarFieldConfig;
  runtime: StarRuntime;
}

interface ParticleBuffers {
  geometry: THREE.BufferGeometry;
  trailGeometry: LineSegmentsGeometry;
  positions: Float32Array;
  basePositions: Float32Array;
  sourcePositions: Float32Array;
  targetPositions: Float32Array;
  previousPositions: Float32Array;
  pointSizes: Float32Array;
  baseSizes: Float32Array;
  sourceSizes: Float32Array;
  targetSizes: Float32Array;
  trailPositions: Float32Array;
  activeShape: StarFieldConfig["shape"];
  morphProgress: number;
}

export function StarParticles({ config, runtime }: StarParticlesProps) {
  const { size, viewport } = useThree();
  const pointsRef = useRef<THREE.Points>(null);
  const buffers = useMemo(() => createParticleBuffers(config.shape), []);
  const waveData = useMemo(() => new Float32Array(ENERGY_WAVE_COUNT * 4), []);
  const waveVectors = useMemo(
    () => Array.from({ length: ENERGY_WAVE_COUNT }, () => new THREE.Vector4()),
    []
  );
  const starTarget = useMemo(() => new THREE.Color(config.theme.star), []);
  const glowTarget = useMemo(() => new THREE.Color(config.theme.glow), []);
  const material = useMemo(() => createStarMaterial(config, waveVectors), []);
  const trailMaterial = useMemo(
    () => new LineMaterial({
      color: config.theme.glow,
      transparent: true,
      opacity: 0,
      depthTest: false,
      depthWrite: false,
      blending: THREE.AdditiveBlending
    }),
    []
  );
  const trailObject = useMemo(() => {
    const object = new LineSegments2(buffers.trailGeometry, trailMaterial);
    object.name = "star-trails";
    object.frustumCulled = false;
    object.renderOrder = 0;
    return object;
  }, [buffers.trailGeometry, trailMaterial]);

  useEffect(() => {
    starTarget.set(config.theme.star);
    glowTarget.set(config.theme.glow);
    trailMaterial.color.set(config.theme.glow);
  }, [config.theme.glow, config.theme.star, glowTarget, starTarget, trailMaterial]);

  useEffect(() => {
    if (buffers.activeShape === config.shape) return;
    buffers.sourcePositions.set(buffers.basePositions);
    buffers.sourceSizes.set(buffers.baseSizes);
    buffers.activeShape = config.shape;
    buffers.morphProgress = 0;
  }, [buffers, config.shape]);

  useEffect(() => () => {
    buffers.geometry.dispose();
    buffers.trailGeometry.dispose();
    material.dispose();
    trailMaterial.dispose();
  }, [buffers, material, trailMaterial]);

  useFrame((_, delta) => {
    runtime.setViewport(size.width, size.height);
    runtime.step(delta, performance.now());

    const phase = runtime.simulationSeconds * FLOW_PHASE_PER_SECOND;
    const definition = getGeometryDefinition(buffers.activeShape);
    definition.sample(buffers.targetPositions, buffers.targetSizes, {
      phase,
      columns: GRID_COLUMNS,
      rows: GRID_ROWS
    });

    if (buffers.morphProgress < 1) {
      const duration = Math.max(0.12, config.motion.morphDuration);
      buffers.morphProgress = Math.min(1, buffers.morphProgress + delta / duration);
      const eased = smoothstep(buffers.morphProgress);
      interpolateBuffers(
        buffers.basePositions,
        buffers.sourcePositions,
        buffers.targetPositions,
        eased
      );
      interpolateBuffers(buffers.baseSizes, buffers.sourceSizes, buffers.targetSizes, eased);
    } else {
      buffers.basePositions.set(buffers.targetPositions);
      buffers.baseSizes.set(buffers.targetSizes);
    }

    rotatePositions(buffers.basePositions, buffers.positions, runtime.rotationX, runtime.rotationY);
    buffers.pointSizes.set(buffers.baseSizes);
    updateTrails(
      buffers,
      runtime.trailStrength
    );

    const positionAttribute = buffers.geometry.getAttribute("position") as THREE.BufferAttribute;
    const sizeAttribute = buffers.geometry.getAttribute("aPointSize") as THREE.BufferAttribute;
    const trailAttribute = buffers.trailGeometry.getAttribute(
      "instanceStart"
    ) as THREE.InterleavedBufferAttribute;
    positionAttribute.needsUpdate = true;
    sizeAttribute.needsUpdate = true;
    trailAttribute.data.needsUpdate = runtime.trailStrength > TRAIL_VISIBILITY_THRESHOLD;

    const sceneScale = BASE_SCENE_SCALE * runtime.zoom * (1 + runtime.burstScale);
    pointsRef.current?.scale.setScalar(sceneScale);
    trailObject.scale.setScalar(sceneScale);

    const uniforms = material.uniforms;
    uniforms.uViewport.value.set(size.width, size.height);
    uniforms.uPointer.value.set(runtime.pointerX, runtime.pointerY);
    uniforms.uPixelRatio.value = viewport.dpr;
    uniforms.uPointScale.value = config.motion.pointScale;
    uniforms.uHoverRadius.value = config.effects.hoverRadius;
    uniforms.uLightStrength.value = runtime.lightStrength;
    uniforms.uMagnetStrength.value = runtime.magnetStrength;
    (uniforms.uStarColor.value as THREE.Color).lerp(starTarget, 1 - Math.pow(0.04, delta));
    (uniforms.uGlowColor.value as THREE.Color).lerp(glowTarget, 1 - Math.pow(0.04, delta));

    runtime.writeWaveData(waveData);
    for (let index = 0; index < ENERGY_WAVE_COUNT; index += 1) {
      const sourceIndex = index * 4;
      waveVectors[index].set(
        waveData[sourceIndex],
        waveData[sourceIndex + 1],
        waveData[sourceIndex + 2],
        waveData[sourceIndex + 3]
      );
    }

    trailMaterial.opacity = runtime.trailStrength > TRAIL_VISIBILITY_THRESHOLD
      ? 0.055 + runtime.trailStrength * 0.285
      : 0;
    trailMaterial.uniforms.linewidth.value = (
      0.58 + runtime.trailStrength * 0.88
    ) * viewport.dpr;
  });

  return (
    <>
      <DustTrailLayer
        object={trailObject}
      />
      <StarPointLayer
        objectRef={pointsRef}
        geometry={buffers.geometry}
        material={material}
      />
    </>
  );
}

function createParticleBuffers(initialShape: StarFieldConfig["shape"]): ParticleBuffers {
  const positions = new Float32Array(POINT_COUNT * 3);
  const basePositions = new Float32Array(POINT_COUNT * 3);
  const sourcePositions = new Float32Array(POINT_COUNT * 3);
  const targetPositions = new Float32Array(POINT_COUNT * 3);
  const previousPositions = new Float32Array(POINT_COUNT * 3);
  const pointSizes = new Float32Array(POINT_COUNT);
  const baseSizes = new Float32Array(POINT_COUNT);
  const sourceSizes = new Float32Array(POINT_COUNT);
  const targetSizes = new Float32Array(POINT_COUNT);
  const trailPositions = new Float32Array(TRAIL_SEGMENT_COUNT * 6);
  const definition = getGeometryDefinition(initialShape);

  definition.sample(basePositions, baseSizes, {
    phase: 0,
    columns: GRID_COLUMNS,
    rows: GRID_ROWS
  });
  positions.set(basePositions);
  sourcePositions.set(basePositions);
  targetPositions.set(basePositions);
  pointSizes.set(baseSizes);
  sourceSizes.set(baseSizes);
  targetSizes.set(baseSizes);

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));
  geometry.setAttribute("aPointSize", new THREE.BufferAttribute(pointSizes, 1));

  const trailGeometry = new LineSegmentsGeometry();
  trailGeometry.setPositions(trailPositions);

  return {
    geometry,
    trailGeometry,
    positions,
    basePositions,
    sourcePositions,
    targetPositions,
    previousPositions,
    pointSizes,
    baseSizes,
    sourceSizes,
    targetSizes,
    trailPositions,
    activeShape: initialShape,
    morphProgress: 1
  };
}

function createStarMaterial(
  config: StarFieldConfig,
  waveVectors: THREE.Vector4[]
): THREE.ShaderMaterial {
  return new THREE.ShaderMaterial({
    uniforms: {
      uViewport: { value: new THREE.Vector2(720, 720) },
      uPointer: { value: new THREE.Vector2(360, 360) },
      uPixelRatio: { value: 1 },
      uPointScale: { value: config.motion.pointScale },
      uHoverRadius: { value: config.effects.hoverRadius },
      uLightStrength: { value: 0 },
      uMagnetStrength: { value: 0 },
      uWaveBand: { value: ENERGY_WAVE_BAND_WIDTH },
      uWaves: { value: waveVectors },
      uStarColor: { value: new THREE.Color(config.theme.star) },
      uGlowColor: { value: new THREE.Color(config.theme.glow) }
    },
    vertexShader: starVertexShader,
    fragmentShader: starFragmentShader,
    transparent: true,
    depthWrite: false,
    blending: THREE.NormalBlending
  });
}

function interpolateBuffers(
  output: Float32Array,
  from: Float32Array,
  to: Float32Array,
  progress: number
): void {
  for (let index = 0; index < output.length; index += 1) {
    output[index] = from[index] + (to[index] - from[index]) * progress;
  }
}

function rotatePositions(
  source: Float32Array,
  output: Float32Array,
  rotationX: number,
  rotationY: number
): void {
  const cosX = Math.cos(rotationX);
  const sinX = Math.sin(rotationX);
  const cosY = Math.cos(rotationY);
  const sinY = Math.sin(rotationY);

  for (let index = 0; index < POINT_COUNT; index += 1) {
    const positionIndex = index * 3;
    const x = source[positionIndex];
    const y = source[positionIndex + 1];
    const z = source[positionIndex + 2];
    const rotatedX = x * cosY + z * sinY;
    const yAfterX = -x * sinY + z * cosY;
    output[positionIndex] = rotatedX;
    // Match the original Canvas projection, whose positive Y axis points down.
    output[positionIndex + 1] = -(y * cosX - yAfterX * sinX);
    output[positionIndex + 2] = y * sinX + yAfterX * cosX;
  }
}

function updateTrails(
  buffers: ParticleBuffers,
  strength: number
): void {
  if (strength > TRAIL_VISIBILITY_THRESHOLD) {
    const maxLength = (12 + strength * 24) / BASE_SCENE_SCALE;
    const maxFrameDistance = 60 / BASE_SCENE_SCALE;
    let segmentIndex = 0;

    for (let pointIndex = 0; pointIndex < POINT_COUNT; pointIndex += TRAIL_POINT_STEP) {
      const positionIndex = pointIndex * 3;
      const trailIndex = segmentIndex * 6;
      const currentX = buffers.positions[positionIndex];
      const currentY = buffers.positions[positionIndex + 1];
      const currentZ = buffers.positions[positionIndex + 2];
      const deltaX = currentX - buffers.previousPositions[positionIndex];
      const deltaY = currentY - buffers.previousPositions[positionIndex + 1];
      const deltaZ = currentZ - buffers.previousPositions[positionIndex + 2];
      const distance = Math.hypot(deltaX, deltaY, deltaZ);
      const validDistance = distance >= 0.001 && distance <= maxFrameDistance;
      const stretch = validDistance
        ? Math.min(1.05 + strength * 3.5, maxLength / distance)
        : 0;

      buffers.trailPositions[trailIndex] = currentX - deltaX * stretch;
      buffers.trailPositions[trailIndex + 1] = currentY - deltaY * stretch;
      buffers.trailPositions[trailIndex + 2] = currentZ - deltaZ * stretch;
      buffers.trailPositions[trailIndex + 3] = currentX;
      buffers.trailPositions[trailIndex + 4] = currentY;
      buffers.trailPositions[trailIndex + 5] = currentZ;
      segmentIndex += 1;
    }
  }

  // The original Canvas effect measured displacement against the actual previous frame.
  buffers.previousPositions.set(buffers.positions);
}

function smoothstep(value: number): number {
  return value * value * (3 - value * 2);
}

import type { RuntimeStatus, StarFieldConfig } from "@/components/formfield/domain";

const FRAME_DURATION_MS = 1000 / 60;
const LONG_PRESS_DELAY_MS = 280;
const DRAG_THRESHOLD_PX = 8;
const DEFAULT_ROTATION_X = 0.5;
const DEFAULT_ROTATION_Y = -0.5;
const ENERGY_WAVE_DURATION_SECONDS = 1.05;
const ENERGY_WAVE_BAND_PX = 38;

export const ENERGY_WAVE_COUNT = 4;

type StatusListener = (status: RuntimeStatus) => void;

interface FinishPointerEvent {
  pointerId: number;
  clientX?: number;
  clientY?: number;
  pointerType?: string;
}

export class StarRuntime {
  config: StarFieldConfig;
  rotationX = DEFAULT_ROTATION_X;
  rotationY = DEFAULT_ROTATION_Y;
  velocityX = 0;
  velocityY = 0;
  zoom = 1;
  lightStrength = 0;
  magnetStrength = 0;
  burstScale = 0;
  simulationSeconds = 0;
  pointerX = 360;
  pointerY = 360;
  viewportWidth = 720;
  viewportHeight = 720;
  trailStrength = 0;
  timeScale = 1;

  readonly waveX = new Float32Array(ENERGY_WAVE_COUNT);
  readonly waveY = new Float32Array(ENERGY_WAVE_COUNT);
  readonly waveRadius = new Float32Array(ENERGY_WAVE_COUNT);
  readonly wavePower = new Float32Array(ENERGY_WAVE_COUNT);

  private canvas: HTMLCanvasElement | null = null;
  private statusListener?: StatusListener;
  private status: RuntimeStatus = "disabled";
  private pointerInside = false;
  private dragging = false;
  private activePointerId: number | null = null;
  private pressCandidate = false;
  private dragMoved = false;
  private pressStartedAt = 0;
  private pressStartClientX = 0;
  private pressStartClientY = 0;
  private lastClientX = 0;
  private lastClientY = 0;
  private lastPointerAt = 0;
  private magnetMode = 0;
  private magnetPolarity = 1;
  private freezeEngaged = false;
  private targetZoom = 1;
  private resetting = false;
  private waveCursor = 0;
  private readonly waveStartedAt = new Float64Array(ENERGY_WAVE_COUNT);
  private readonly waveActive = new Uint8Array(ENERGY_WAVE_COUNT);

  constructor(config: StarFieldConfig, statusListener?: StatusListener) {
    this.config = config;
    this.statusListener = statusListener;
    this.emitStatus(true);
  }

  setConfig(config: StarFieldConfig): void {
    const interactionWasEnabled = this.config.interaction.enabled;
    this.config = config;

    if (interactionWasEnabled && !config.interaction.enabled) {
      this.cancelPointer();
      this.velocityX = 0;
      this.velocityY = 0;
    }

    if (config.interaction.holdMode === "freeze") {
      this.setMagnetMode(0);
    } else {
      this.setFreezeEngaged(false);
    }

    this.syncCanvasClasses();
    this.emitStatus();
  }

  setStatusListener(listener?: StatusListener): void {
    this.statusListener = listener;
    this.emitStatus(true);
  }

  setViewport(width: number, height: number): void {
    this.viewportWidth = width;
    this.viewportHeight = height;
  }

  attach(canvas: HTMLCanvasElement): () => void {
    this.canvas = canvas;
    canvas.addEventListener("pointerdown", this.handlePointerDown);
    canvas.addEventListener("pointermove", this.handlePointerMove);
    canvas.addEventListener("pointerup", this.handlePointerUp);
    canvas.addEventListener("pointercancel", this.handlePointerCancel);
    canvas.addEventListener("lostpointercapture", this.handleLostPointerCapture);
    canvas.addEventListener("pointerenter", this.handlePointerEnter);
    canvas.addEventListener("pointerleave", this.handlePointerLeave);
    canvas.addEventListener("wheel", this.handleWheel, { passive: false });
    canvas.addEventListener("dblclick", this.handleDoubleClick);
    canvas.addEventListener("contextmenu", this.handleContextMenu);
    window.addEventListener("blur", this.handleWindowBlur);
    this.syncCanvasClasses();

    return () => {
      this.cancelPointer();
      canvas.removeEventListener("pointerdown", this.handlePointerDown);
      canvas.removeEventListener("pointermove", this.handlePointerMove);
      canvas.removeEventListener("pointerup", this.handlePointerUp);
      canvas.removeEventListener("pointercancel", this.handlePointerCancel);
      canvas.removeEventListener("lostpointercapture", this.handleLostPointerCapture);
      canvas.removeEventListener("pointerenter", this.handlePointerEnter);
      canvas.removeEventListener("pointerleave", this.handlePointerLeave);
      canvas.removeEventListener("wheel", this.handleWheel);
      canvas.removeEventListener("dblclick", this.handleDoubleClick);
      canvas.removeEventListener("contextmenu", this.handleContextMenu);
      window.removeEventListener("blur", this.handleWindowBlur);
      canvas.classList.remove(
        "is-interactive",
        "is-dragging",
        "is-attracting",
        "is-repelling",
        "is-freezing"
      );
      if (this.canvas === canvas) this.canvas = null;
    };
  }

  resetView(): void {
    this.resetting = true;
    this.targetZoom = 1;
  }

  step(deltaSeconds: number, nowMs: number): void {
    const deltaFrames = Math.min(3, Math.max(0.25, deltaSeconds * 60));

    if (
      this.config.interaction.enabled
      && this.dragging
      && this.pressCandidate
      && this.magnetMode === 0
      && !this.freezeEngaged
      && nowMs - this.pressStartedAt >= LONG_PRESS_DELAY_MS
    ) {
      if (this.config.interaction.holdMode === "freeze") {
        this.setFreezeEngaged(true);
      } else {
        this.setMagnetMode(this.magnetPolarity);
      }
    }

    const timeScaleTarget = this.freezeEngaged ? 0 : 1;
    const timeScaleEase = 1 - Math.pow(this.freezeEngaged ? 0.62 : 0.88, deltaFrames);
    this.timeScale += (timeScaleTarget - this.timeScale) * timeScaleEase;
    if (this.freezeEngaged && this.timeScale < 0.001) this.timeScale = 0;
    if (!this.freezeEngaged && 1 - this.timeScale < 0.001) this.timeScale = 1;

    if (this.resetting) {
      const resetEase = 1 - Math.pow(0.8, deltaFrames);
      const deltaX = shortestAngle(this.rotationX, DEFAULT_ROTATION_X);
      const deltaY = shortestAngle(this.rotationY, DEFAULT_ROTATION_Y);
      this.rotationX += deltaX * resetEase;
      this.rotationY += deltaY * resetEase;
      this.velocityX = 0;
      this.velocityY = 0;

      if (Math.abs(deltaX) + Math.abs(deltaY) < 0.001) {
        this.rotationX = DEFAULT_ROTATION_X;
        this.rotationY = DEFAULT_ROTATION_Y;
        this.resetting = false;
      }
    } else if (this.config.interaction.enabled && !this.dragging) {
      this.rotationX += this.velocityX * deltaFrames * this.timeScale;
      this.rotationY += this.velocityY * deltaFrames * this.timeScale;
      const damping = Math.pow(0.9, deltaFrames * this.timeScale);
      this.velocityX *= damping;
      this.velocityY *= damping;
      if (Math.abs(this.velocityX) < 0.00002) this.velocityX = 0;
      if (Math.abs(this.velocityY) < 0.00002) this.velocityY = 0;
    }

    const magnetTarget = this.config.interaction.enabled && this.dragging ? this.magnetMode : 0;
    const magnetEase = 1 - Math.pow(magnetTarget === 0 ? 0.78 : 0.66, deltaFrames);
    this.magnetStrength += (magnetTarget - this.magnetStrength) * magnetEase;

    const lightTarget = this.pointerInside ? this.config.effects.hoverIntensity : 0;
    const lightEase = 1 - Math.pow(lightTarget > this.lightStrength ? 0.45 : 0.82, deltaFrames);
    this.lightStrength += (lightTarget - this.lightStrength) * lightEase;
    this.burstScale *= Math.pow(0.84, deltaFrames);

    const zoomEase = 1 - Math.pow(0.76, deltaFrames);
    this.zoom += (this.targetZoom - this.zoom) * zoomEase;
    if (Math.abs(this.targetZoom - this.zoom) < 0.0001) this.zoom = this.targetZoom;

    this.simulationSeconds += deltaFrames / 60 * this.timeScale * this.config.motion.flowSpeed;
    this.updateEnergyWaves();

    const motionSpeed = Math.hypot(this.velocityX, this.velocityY);
    const normalizedSpeed = this.config.interaction.enabled
      ? clamp01((motionSpeed - 0.014) / 0.05)
      : 0;
    const easedSpeed = normalizedSpeed * normalizedSpeed * (3 - normalizedSpeed * 2);
    const normalizedIntensity = clamp01(this.config.effects.trailIntensity / 1.5);
    this.trailStrength = easedSpeed * normalizedIntensity * 0.9;
  }

  writeWaveData(target: Float32Array): void {
    for (let index = 0; index < ENERGY_WAVE_COUNT; index += 1) {
      const targetIndex = index * 4;
      target[targetIndex] = this.waveX[index];
      target[targetIndex + 1] = this.waveY[index];
      target[targetIndex + 2] = this.waveRadius[index];
      target[targetIndex + 3] = this.wavePower[index];
    }
  }

  private readonly handlePointerDown = (event: PointerEvent): void => {
    if (!this.config.interaction.enabled || event.button !== 0 || this.dragging) return;
    event.preventDefault();
    this.activePointerId = event.pointerId;
    this.dragging = true;
    this.dragMoved = false;
    this.pressCandidate = true;
    this.pressStartedAt = performance.now();
    this.pressStartClientX = event.clientX;
    this.pressStartClientY = event.clientY;
    this.magnetPolarity = event.shiftKey ? -1 : 1;
    this.setMagnetMode(0);
    this.resetting = false;
    this.velocityX = 0;
    this.velocityY = 0;
    this.lastClientX = event.clientX;
    this.lastClientY = event.clientY;
    this.lastPointerAt = event.timeStamp;
    this.updatePointerPosition(event.clientX, event.clientY);
    this.pointerInside = true;
    this.canvas?.setPointerCapture(event.pointerId);
    this.syncCanvasClasses();
    this.emitStatus();
  };

  private readonly handlePointerMove = (event: PointerEvent): void => {
    this.pointerInside = true;

    if (!this.dragging) {
      this.updatePointerPosition(event.clientX, event.clientY);
      return;
    }
    if (event.pointerId !== this.activePointerId || !this.config.interaction.enabled) return;

    event.preventDefault();
    const coalescedEvents = event.getCoalescedEvents?.() ?? [];
    const samples = coalescedEvents.length > 0 ? coalescedEvents : [event];

    for (const sample of samples) {
      const bounds = this.updatePointerPosition(sample.clientX, sample.clientY);
      if (this.pressCandidate && this.magnetMode === 0) {
        this.magnetPolarity = sample.shiftKey ? -1 : 1;
      }

      if (this.magnetMode !== 0 || this.freezeEngaged) {
        this.updateLastPointerSample(sample);
        continue;
      }

      if (!this.dragMoved) {
        const distanceFromPress = Math.hypot(
          sample.clientX - this.pressStartClientX,
          sample.clientY - this.pressStartClientY
        );
        if (distanceFromPress > DRAG_THRESHOLD_PX) {
          this.dragMoved = true;
          this.pressCandidate = false;
        }
      }

      if (!this.dragMoved) {
        this.updateLastPointerSample(sample);
        continue;
      }

      const deltaX = (sample.clientX - this.lastClientX) * Math.PI / bounds.width * 0.78;
      const deltaY = (sample.clientY - this.lastClientY) * Math.PI / bounds.height * 0.78;
      const elapsed = Math.max(4, sample.timeStamp - this.lastPointerAt);
      const velocityScale = FRAME_DURATION_MS / elapsed;
      this.rotationX += deltaY;
      this.rotationY += deltaX;
      this.velocityX = this.velocityX * 0.68 + deltaY * velocityScale * 0.32;
      this.velocityY = this.velocityY * 0.68 + deltaX * velocityScale * 0.32;
      this.updateLastPointerSample(sample);
    }
  };

  private readonly handlePointerUp = (event: PointerEvent): void => {
    this.finishPointer(event, false);
  };

  private readonly handlePointerCancel = (event: PointerEvent): void => {
    this.finishPointer(event, true);
  };

  private readonly handleLostPointerCapture = (event: PointerEvent): void => {
    this.finishPointer(event, true);
  };

  private readonly handlePointerEnter = (event: PointerEvent): void => {
    this.pointerInside = true;
    this.updatePointerPosition(event.clientX, event.clientY);
    this.lightStrength = Math.max(this.lightStrength, this.config.effects.hoverIntensity * 0.55);
  };

  private readonly handlePointerLeave = (): void => {
    this.pointerInside = false;
  };

  private readonly handleWheel = (event: WheelEvent): void => {
    if (!this.config.interaction.enabled) return;
    event.preventDefault();
    this.updatePointerPosition(event.clientX, event.clientY);
    this.pointerInside = true;
    const delta = event.deltaMode === 1
      ? event.deltaY * 16
      : (event.deltaMode === 2 ? event.deltaY * this.viewportHeight : event.deltaY);
    this.targetZoom = Math.min(1.5, Math.max(0.62, this.targetZoom * Math.exp(-delta * 0.0014)));
    this.lightStrength = Math.max(this.lightStrength, this.config.effects.hoverIntensity * 0.5);
  };

  private readonly handleDoubleClick = (event: MouseEvent): void => {
    if (!this.config.interaction.enabled) return;
    event.preventDefault();
    this.resetView();
  };

  private readonly handleContextMenu = (event: MouseEvent): void => {
    if (this.config.interaction.enabled) event.preventDefault();
  };

  private readonly handleWindowBlur = (): void => {
    this.pointerInside = false;
    this.cancelPointer();
  };

  private finishPointer(event: FinishPointerEvent, cancelled: boolean): void {
    if (!this.dragging || event.pointerId !== this.activePointerId) return;
    if (Number.isFinite(event.clientX) && Number.isFinite(event.clientY)) {
      this.updatePointerPosition(event.clientX as number, event.clientY as number);
    }

    const heldLongEnough = performance.now() - this.pressStartedAt >= LONG_PRESS_DELAY_MS;
    const usedHoldAction = this.magnetMode !== 0
      || this.freezeEngaged
      || (this.pressCandidate && heldLongEnough);
    const shouldPulse = !cancelled && this.pressCandidate && !this.dragMoved && !usedHoldAction;
    const pointerId = this.activePointerId;
    this.dragging = false;
    this.pressCandidate = false;
    this.dragMoved = false;
    this.pressStartedAt = 0;
    this.setMagnetMode(0);
    this.setFreezeEngaged(false);

    if (shouldPulse) {
      this.emitEnergyWave(this.pointerX, this.pointerY);
    } else if (!cancelled) {
      this.burstScale = Math.max(
        this.burstScale,
        Math.min(0.035, Math.hypot(this.velocityX, this.velocityY) * 0.35)
      );
    }

    if (event.pointerType && event.pointerType !== "mouse") this.pointerInside = false;
    if (pointerId !== null && this.canvas?.hasPointerCapture(pointerId)) {
      this.canvas.releasePointerCapture(pointerId);
    }
    this.activePointerId = null;
    this.syncCanvasClasses();
    this.emitStatus();
  }

  private cancelPointer(): void {
    if (this.dragging && this.activePointerId !== null) {
      this.finishPointer({ pointerId: this.activePointerId }, true);
    }
    this.dragging = false;
    this.activePointerId = null;
    this.pressCandidate = false;
    this.dragMoved = false;
    this.setMagnetMode(0);
    this.setFreezeEngaged(false);
    this.syncCanvasClasses();
    this.emitStatus();
  }

  private updatePointerPosition(clientX: number, clientY: number): DOMRect {
    const bounds = this.canvas?.getBoundingClientRect() ?? new DOMRect(0, 0, 720, 720);
    this.pointerX = clientX - bounds.left;
    this.pointerY = clientY - bounds.top;
    this.setViewport(bounds.width, bounds.height);
    return bounds;
  }

  private updateLastPointerSample(sample: PointerEvent): void {
    this.lastClientX = sample.clientX;
    this.lastClientY = sample.clientY;
    this.lastPointerAt = sample.timeStamp;
  }

  private setMagnetMode(mode: number): void {
    const normalizedMode = Math.sign(mode);
    if (this.magnetMode === normalizedMode) return;
    this.magnetMode = normalizedMode;
    this.syncCanvasClasses();
    this.emitStatus();
  }

  private setFreezeEngaged(enabled: boolean): void {
    if (this.freezeEngaged === enabled) return;
    this.freezeEngaged = enabled;
    this.syncCanvasClasses();
    this.emitStatus();
  }

  private emitEnergyWave(x: number, y: number): void {
    const slot = this.waveCursor;
    this.waveX[slot] = x;
    this.waveY[slot] = y;
    this.waveStartedAt[slot] = this.simulationSeconds;
    this.waveActive[slot] = 1;
    this.waveCursor = (this.waveCursor + 1) % ENERGY_WAVE_COUNT;
    this.burstScale = Math.max(this.burstScale, 0.018);
  }

  private updateEnergyWaves(): void {
    const maxRadius = Math.hypot(this.viewportWidth, this.viewportHeight) * 1.05;

    for (let index = 0; index < ENERGY_WAVE_COUNT; index += 1) {
      if (!this.waveActive[index]) {
        this.wavePower[index] = 0;
        continue;
      }

      const progress = (this.simulationSeconds - this.waveStartedAt[index])
        / ENERGY_WAVE_DURATION_SECONDS;
      if (progress >= 1) {
        this.waveActive[index] = 0;
        this.wavePower[index] = 0;
        continue;
      }

      this.waveRadius[index] = progress * maxRadius;
      this.wavePower[index] = Math.pow(1 - progress, 0.42);
    }
  }

  private syncCanvasClasses(): void {
    if (!this.canvas) return;
    this.canvas.classList.toggle("is-interactive", this.config.interaction.enabled);
    this.canvas.classList.toggle("is-dragging", this.dragging && this.magnetMode === 0 && !this.freezeEngaged);
    this.canvas.classList.toggle("is-attracting", this.magnetMode > 0);
    this.canvas.classList.toggle("is-repelling", this.magnetMode < 0);
    this.canvas.classList.toggle("is-freezing", this.freezeEngaged);
  }

  private emitStatus(force = false): void {
    const nextStatus: RuntimeStatus = !this.config.interaction.enabled
      ? "disabled"
      : this.freezeEngaged
        ? "frozen"
        : this.magnetMode > 0
          ? "attracting"
          : this.magnetMode < 0
            ? "repelling"
            : this.dragging
              ? "dragging"
              : "idle";

    if (!force && nextStatus === this.status) return;
    this.status = nextStatus;
    this.statusListener?.(nextStatus);
  }
}

export const ENERGY_WAVE_BAND_WIDTH = ENERGY_WAVE_BAND_PX;

function shortestAngle(from: number, to: number): number {
  return Math.atan2(Math.sin(to - from), Math.cos(to - from));
}

function clamp01(value: number): number {
  return Math.min(1, Math.max(0, value));
}

import { useEffect, useMemo, type MutableRefObject } from "react";
import { useFrame, useThree } from "@react-three/fiber";
import * as THREE from "three";
import type { RuntimeStatus, StarFieldConfig } from "@/components/formfield/domain";
import { StarParticles } from "@/components/formfield/StarParticles";
import { StarRuntime } from "@/components/formfield/StarRuntime";

export interface StarFieldController {
  resetView(): void;
}

interface StarSceneProps {
  config: StarFieldConfig;
  controllerRef: MutableRefObject<StarFieldController | null>;
  onRuntimeStatusChange?: (status: RuntimeStatus) => void;
}

export function StarScene({ config, controllerRef, onRuntimeStatusChange }: StarSceneProps) {
  const runtime = useMemo(() => new StarRuntime(config, onRuntimeStatusChange), []);

  useEffect(() => {
    runtime.setConfig(config);
  }, [config, runtime]);

  useEffect(() => {
    runtime.setStatusListener(onRuntimeStatusChange);
  }, [onRuntimeStatusChange, runtime]);

  useEffect(() => {
    controllerRef.current = {
      resetView: () => runtime.resetView()
    };
    return () => {
      controllerRef.current = null;
    };
  }, [controllerRef, runtime]);

  return (
    <>
      <SceneBindings config={config} runtime={runtime} />
      <StarParticles config={config} runtime={runtime} />
    </>
  );
}

function SceneBindings({ config, runtime }: { config: StarFieldConfig; runtime: StarRuntime }) {
  const { gl, scene } = useThree();
  const backgroundTarget = useMemo(() => new THREE.Color(config.theme.background), []);

  useEffect(() => runtime.attach(gl.domElement), [gl, runtime]);

  useEffect(() => {
    backgroundTarget.set(config.theme.background);
  }, [backgroundTarget, config.theme.background]);

  useEffect(() => {
    if (!(scene.background instanceof THREE.Color)) {
      scene.background = new THREE.Color(config.theme.background);
    }
  }, [config.theme.background, scene]);

  useFrame((_, delta) => {
    if (scene.background instanceof THREE.Color) {
      scene.background.lerp(backgroundTarget, 1 - Math.pow(0.04, delta));
    }
  }, -1);

  return null;
}

export const starVertexShader = /* glsl */ `
  attribute float aPointSize;

  uniform vec2 uViewport;
  uniform vec2 uPointer;
  uniform float uPixelRatio;
  uniform float uPointScale;
  uniform float uHoverRadius;
  uniform float uLightStrength;
  uniform float uMagnetStrength;
  uniform float uWaveBand;
  uniform vec4 uWaves[4];

  varying float vGlow;

  void main() {
    vec4 viewPosition = modelViewMatrix * vec4(position, 1.0);
    vec4 clipPosition = projectionMatrix * viewPosition;
    vec2 ndc = clipPosition.xy / clipPosition.w;
    vec2 screenPosition = vec2(
      (ndc.x * 0.5 + 0.5) * uViewport.x,
      (1.0 - (ndc.y * 0.5 + 0.5)) * uViewport.y
    );

    float pointerDistance = distance(screenPosition, uPointer);
    float normalizedPointerDistance = min(1.0, pointerDistance / uHoverRadius);
    float hoverInfluence = pow(
      1.0 - normalizedPointerDistance * normalizedPointerDistance,
      2.0
    );
    float illumination = hoverInfluence * uLightStrength;

    if (abs(uMagnetStrength) > 0.001) {
      screenPosition += (uPointer - screenPosition)
        * hoverInfluence
        * uMagnetStrength
        * 0.24;
    }

    float waveGlow = 0.0;
    vec2 waveOffset = vec2(0.0);

    for (int index = 0; index < 4; index += 1) {
      vec4 wave = uWaves[index];
      if (wave.w <= 0.001) continue;
      vec2 fromWave = screenPosition - wave.xy;
      float waveDistance = length(fromWave);
      float distanceFromFront = abs(waveDistance - wave.z);
      if (distanceFromFront >= uWaveBand) continue;
      float ridge = 1.0 - distanceFromFront / uWaveBand;
      float influence = ridge * ridge * wave.w;
      waveGlow = max(waveGlow, influence);
      if (waveDistance > 0.001) {
        waveOffset += normalize(fromWave) * influence * 12.0;
      }
    }

    screenPosition += waveOffset;
    ndc = vec2(
      screenPosition.x / uViewport.x * 2.0 - 1.0,
      (1.0 - screenPosition.y / uViewport.y) * 2.0 - 1.0
    );
    clipPosition.xy = ndc * clipPosition.w;
    gl_Position = clipPosition;

    vGlow = max(illumination, waveGlow);
    float perspectiveScale = 520.0 / max(260.0, -viewPosition.z);
    float baseSize = max(0.32, aPointSize * 2.15 * uPointScale * perspectiveScale);
    gl_PointSize = baseSize * (1.0 + vGlow * 1.35) * uPixelRatio;
  }
`;

export const starFragmentShader = /* glsl */ `
  uniform vec3 uStarColor;
  uniform vec3 uGlowColor;

  varying float vGlow;

  void main() {
    float radius = distance(gl_PointCoord, vec2(0.5));
    float glowAmount = clamp(vGlow, 0.0, 1.0);
    float coreRadius = mix(0.47, 0.25, glowAmount);
    float core = 1.0 - smoothstep(coreRadius - 0.075, coreRadius, radius);
    float sprite = 1.0 - smoothstep(0.43, 0.5, radius);
    float halo = max(0.0, sprite - core) * glowAmount * 0.64;
    float alpha = max(core, halo);

    if (alpha < 0.01) discard;

    vec3 color = mix(uStarColor, uGlowColor, glowAmount);
    gl_FragColor = vec4(color, alpha);
    #include <tonemapping_fragment>
    #include <colorspace_fragment>
  }
`;

