import type { GeometryDefinition } from "@/components/formfield/geometries/types";

const STEP = Math.PI / 40;
const RADIUS = 90;

export const torusGeometry: GeometryDefinition = {
  id: "torus",
  label: "星环",
  ariaLabel: "由星点组成并持续流动的三维星环",
  mark: "torus",
  sample(positions, pointSizes, { phase, columns, rows }) {
    let index = 0;

    for (let row = 0; row < rows; row += 1) {
      const v = row * STEP * 2 + phase * 2;
      const sinV = Math.sin(v);
      const cosV = Math.cos(v);
      const ringRadius = (2 + sinV) * RADIUS;

      for (let column = 0; column < columns; column += 1) {
        const u = column * STEP + phase;
        const positionIndex = index * 3;
        positions[positionIndex] = ringRadius * Math.cos(u);
        positions[positionIndex + 1] = ringRadius * Math.sin(u);
        positions[positionIndex + 2] = cosV * RADIUS;
        pointSizes[index] = Math.abs(cosV + 0.3);
        index += 1;
      }
    }
  }
};

import type { GeometryDefinition } from "@/components/formfield/geometries/types";

const RADIUS = 225;

export const sphereGeometry: GeometryDefinition = {
  id: "sphere",
  label: "球体",
  ariaLabel: "由星点组成并持续流动的三维球体",
  mark: "sphere",
  sample(positions, pointSizes, { phase, columns, rows }) {
    let index = 0;

    for (let row = 0; row < rows; row += 1) {
      const latitude = ((row + 0.5) / rows - 0.5) * Math.PI;
      const sinLatitude = Math.sin(latitude);
      const cosLatitude = Math.cos(latitude);
      const radial = RADIUS * cosLatitude;

      for (let column = 0; column < columns; column += 1) {
        const longitude = column / columns * Math.PI * 2 + phase;
        const positionIndex = index * 3;
        positions[positionIndex] = radial * Math.cos(longitude);
        positions[positionIndex + 1] = radial * Math.sin(longitude);
        positions[positionIndex + 2] = RADIUS * sinLatitude;
        pointSizes[index] = 0.36 + Math.abs(cosLatitude) * 0.94;
        index += 1;
      }
    }
  }
};

import type { GeometryDefinition } from "@/components/formfield/geometries/types";

const RING_RADIUS = 176;
const HALF_WIDTH = 88;

export const mobiusGeometry: GeometryDefinition = {
  id: "mobius",
  label: "莫比乌斯",
  ariaLabel: "由星点组成并持续流动的莫比乌斯环",
  mark: "mobius",
  sample(positions, pointSizes, { phase, columns, rows }) {
    let index = 0;

    for (let row = 0; row < rows; row += 1) {
      const stripOffset = (((row + 0.5) / rows) * 2 - 1) * HALF_WIDTH;
      const normalizedStrip = Math.abs(stripOffset) / HALF_WIDTH;

      for (let column = 0; column < columns; column += 1) {
        const u = column / columns * Math.PI * 2 + phase;
        const halfU = u * 0.5;
        const radial = RING_RADIUS + stripOffset * Math.cos(halfU);
        const positionIndex = index * 3;
        positions[positionIndex] = radial * Math.cos(u);
        positions[positionIndex + 1] = radial * Math.sin(u);
        positions[positionIndex + 2] = stripOffset * Math.sin(halfU);
        pointSizes[index] = 0.48
          + (1 - normalizedStrip * 0.35) * (0.52 + Math.abs(Math.cos(halfU)) * 0.2);
        index += 1;
      }
    }
  }
};

import type { GeometryDefinition } from "@/components/formfield/geometries/types";

const TAU = Math.PI * 2;
const GOLDEN_ANGLE = Math.PI * (3 - Math.sqrt(5));
const PATH_SCALE = 72;
const BUNDLE_RADIUS = 11.5;

export const torusKnotGeometry: GeometryDefinition = {
  id: "torus-knot",
  label: "三叶结",
  ariaLabel: "由星点组成并持续流动的三叶环面结",
  mark: "torus-knot",
  sample(positions, pointSizes, { phase, columns, rows }) {
    const pointCount = columns * rows;
    let index = 0;

    for (let row = 0; row < rows; row += 1) {
      for (let column = 0; column < columns; column += 1) {
        const sampleOrder = column * rows + row;
        const progress = (sampleOrder + 0.5) / pointCount;
        const pathAngle = progress * TAU;
        const u = pathAngle + phase * 0.44;
        const sin2U = Math.sin(2 * u);
        const cos2U = Math.cos(2 * u);
        const sin3U = Math.sin(3 * u);
        const cos3U = Math.cos(3 * u);
        const radial = 2 + cos3U;
        const centerX = radial * cos2U * PATH_SCALE;
        const centerY = radial * sin2U * PATH_SCALE;
        const centerZ = sin3U * PATH_SCALE;

        let tangentX = -3 * sin3U * cos2U - 2 * radial * sin2U;
        let tangentY = -3 * sin3U * sin2U + 2 * radial * cos2U;
        let tangentZ = 3 * cos3U;
        const tangentLength = Math.hypot(tangentX, tangentY, tangentZ);
        tangentX /= tangentLength;
        tangentY /= tangentLength;
        tangentZ /= tangentLength;

        const normalX = cos3U * cos2U;
        const normalY = cos3U * sin2U;
        const normalZ = sin3U;
        const binormalX = tangentY * normalZ - tangentZ * normalY;
        const binormalY = tangentZ * normalX - tangentX * normalZ;
        const binormalZ = tangentX * normalY - tangentY * normalX;
        const radialSeed = fract(
          (row + 1) * 0.754877666
          + (column + 1) * 0.569840296
        );
        const dustRadius = 0.7 + radialSeed * radialSeed * BUNDLE_RADIUS;
        const dustAngle = row * GOLDEN_ANGLE + column * 0.43 + phase * 1.05;
        const cosDust = Math.cos(dustAngle);
        const sinDust = Math.sin(dustAngle);
        const offsetX = (normalX * cosDust + binormalX * sinDust) * dustRadius;
        const offsetY = (normalY * cosDust + binormalY * sinDust) * dustRadius;
        const offsetZ = (normalZ * cosDust + binormalZ * sinDust) * dustRadius;
        const energy = 0.5 + Math.sin(pathAngle * 6 - phase * 5.8) * 0.5;
        const coreWeight = 1 - (dustRadius - 0.7) / BUNDLE_RADIUS;
        const positionIndex = index * 3;

        positions[positionIndex] = centerX + offsetX;
        positions[positionIndex + 1] = centerY + offsetY;
        positions[positionIndex + 2] = centerZ + offsetZ;
        pointSizes[index] = 0.42 + coreWeight * 0.32 + energy * 0.28;
        index += 1;
      }
    }
  }
};

function fract(value: number): number {
  return value - Math.floor(value);
}

import type { GeometryDefinition } from "@/components/formfield/geometries/types";

const TAU = Math.PI * 2;
const SCALE = 66;

export const kleinBottleGeometry: GeometryDefinition = {
  id: "klein",
  label: "克莱因瓶",
  ariaLabel: "由星点组成并持续流动的克莱因瓶曲面",
  mark: "klein",
  sample(positions, pointSizes, { phase, columns, rows }) {
    let index = 0;

    for (let row = 0; row < rows; row += 1) {
      const v = row / rows * TAU + phase * 1.1;
      const sinV = Math.sin(v);
      const sin2V = Math.sin(2 * v);
      const cosV = Math.cos(v);

      for (let column = 0; column < columns; column += 1) {
        const u = column / columns * TAU + phase * 0.42;
        const halfU = u * 0.5;
        const sinHalfU = Math.sin(halfU);
        const cosHalfU = Math.cos(halfU);
        const radial = 2.1 + cosHalfU * sinV - sinHalfU * sin2V;
        const positionIndex = index * 3;

        positions[positionIndex] = radial * Math.cos(u) * SCALE;
        positions[positionIndex + 1] = radial * Math.sin(u) * SCALE;
        positions[positionIndex + 2] = (
          sinHalfU * sinV + cosHalfU * sin2V
        ) * SCALE;
        pointSizes[index] = 0.42 + Math.abs(cosV + 0.24) * 0.72;
        index += 1;
      }
    }
  }
};

import type { GeometryDefinition } from "@/components/formfield/geometries/types";

const TAU = Math.PI * 2;
const RADIUS = 218;
const LATITUDE_EXPONENT = 0.5;
const LONGITUDE_EXPONENT = 0.46;

export const superellipsoidGeometry: GeometryDefinition = {
  id: "superellipsoid",
  label: "超椭球",
  ariaLabel: "由星点组成并持续流动的超椭球曲面",
  mark: "superellipsoid",
  sample(positions, pointSizes, { phase, columns, rows }) {
    let index = 0;

    for (let row = 0; row < rows; row += 1) {
      const latitude = ((row + 0.5) / rows - 0.5) * Math.PI;
      const signedCosLatitude = signedPower(Math.cos(latitude), LATITUDE_EXPONENT);
      const signedSinLatitude = signedPower(Math.sin(latitude), LATITUDE_EXPONENT);

      for (let column = 0; column < columns; column += 1) {
        const longitude = column / columns * TAU + phase * 0.7;
        const positionIndex = index * 3;

        positions[positionIndex] = RADIUS
          * signedCosLatitude
          * signedPower(Math.cos(longitude), LONGITUDE_EXPONENT);
        positions[positionIndex + 1] = RADIUS
          * signedCosLatitude
          * signedPower(Math.sin(longitude), LONGITUDE_EXPONENT);
        positions[positionIndex + 2] = RADIUS * signedSinLatitude;
        pointSizes[index] = 0.48 + Math.abs(Math.cos(latitude)) * 0.76;
        index += 1;
      }
    }
  }
};

function signedPower(value: number, exponent: number): number {
  return Math.sign(value) * Math.pow(Math.abs(value), exponent);
}

import type { GeometryDefinition } from "@/components/formfield/geometries/types";

const HALF_WIDTH = 210;
const HALF_TURNS = Math.PI * 2.7;
const PITCH = 17;

export const helicoidGeometry: GeometryDefinition = {
  id: "helicoid",
  label: "螺旋面",
  ariaLabel: "由星点组成并持续旋转的螺旋曲面",
  mark: "helicoid",
  sample(positions, pointSizes, { phase, columns, rows }) {
    let index = 0;

    for (let row = 0; row < rows; row += 1) {
      const radial = (((row + 0.5) / rows) * 2 - 1) * HALF_WIDTH;
      const normalizedRadius = Math.abs(radial) / HALF_WIDTH;

      for (let column = 0; column < columns; column += 1) {
        const baseAngle = (column / (columns - 1) * 2 - 1) * HALF_TURNS;
        const angle = baseAngle + phase * 0.82;
        const positionIndex = index * 3;

        positions[positionIndex] = radial * Math.cos(angle);
        positions[positionIndex + 1] = radial * Math.sin(angle);
        positions[positionIndex + 2] = baseAngle * PITCH;
        pointSizes[index] = 0.4 + (1 - normalizedRadius * 0.28) * 0.76;
        index += 1;
      }
    }
  }
};

import type { GeometryDefinition } from "@/components/formfield/geometries/types";

const GOLDEN_ANGLE = Math.PI * (3 - Math.sqrt(5));
const HALF_TURNS = Math.PI * 4;
const HELIX_RADIUS = 80;
const HALF_HEIGHT = 205;
const BUNDLE_RADIUS = 5.4;

export const doubleHelixGeometry: GeometryDefinition = {
  id: "double-helix",
  label: "双螺旋",
  ariaLabel: "由两束相互缠绕的星点链组成的双螺旋",
  mark: "double-helix",
  sample(positions, pointSizes, { phase, columns, rows }) {
    const strandRows = Math.floor(rows / 2);
    const samplesPerStrand = columns * strandRows;
    const verticalPitch = HALF_HEIGHT / HALF_TURNS;
    const binormalLength = Math.hypot(verticalPitch, HELIX_RADIUS);
    let index = 0;

    for (let row = 0; row < rows; row += 1) {
      const strand = row < strandRows ? 0 : 1;
      const lane = row % strandRows;

      for (let column = 0; column < columns; column += 1) {
        const sampleOrder = column * strandRows + lane;
        const progress = (sampleOrder + 0.5) / samplesPerStrand;
        const baseAngle = (progress * 2 - 1) * HALF_TURNS;
        const angle = baseAngle + strand * Math.PI + phase * 0.48;
        const cosAngle = Math.cos(angle);
        const sinAngle = Math.sin(angle);
        const normalX = cosAngle;
        const normalY = sinAngle;
        const binormalX = -verticalPitch * sinAngle / binormalLength;
        const binormalY = verticalPitch * cosAngle / binormalLength;
        const binormalZ = -HELIX_RADIUS / binormalLength;
        const radialSeed = fract(
          (lane + 1) * 0.754877666
          + (column + 1) * 0.569840296
          + strand * 0.438289
        );
        const dustRadius = 0.55 + Math.pow(radialSeed, 1.7) * BUNDLE_RADIUS;
        const dustAngle = lane * GOLDEN_ANGLE
          + column * 0.47
          + strand * Math.PI * 0.25
          + phase * 1.1;
        const cosDust = Math.cos(dustAngle);
        const sinDust = Math.sin(dustAngle);
        const energy = 0.5 + Math.sin(
          baseAngle * 2.15 - phase * 5.2 + strand * Math.PI
        ) * 0.5;
        const coreWeight = 1 - (dustRadius - 0.55) / BUNDLE_RADIUS;
        const positionIndex = index * 3;

        positions[positionIndex] = HELIX_RADIUS * cosAngle
          + (normalX * cosDust + binormalX * sinDust) * dustRadius;
        positions[positionIndex + 1] = HELIX_RADIUS * sinAngle
          + (normalY * cosDust + binormalY * sinDust) * dustRadius;
        positions[positionIndex + 2] = (progress * 2 - 1) * HALF_HEIGHT
          + binormalZ * sinDust * dustRadius;
        pointSizes[index] = 0.43 + coreWeight * 0.34 + energy * 0.27;
        index += 1;
      }
    }
  }
};

function fract(value: number): number {
  return value - Math.floor(value);
}

import type { GeometryDefinition } from "@/components/formfield/geometries/types";

const HALF_SIZE = 210;

export const waveSurfaceGeometry: GeometryDefinition = {
  id: "wave-surface",
